val workChannel = Channel<WorkItem>()

repeat(4) { workerId ->
    launch {
        for (item in workChannel) { process(item) } // 4 workers compete for items
    }
}

suspend fun <T> fanIn(vararg sources: ReceiveChannel<T>, output: SendChannel<T>) = coroutineScope {
    sources.forEach { source ->
        launch { for (value in source) output.send(value) }
    }
}

select<Unit> {
    channelA.onReceive { value -> handleA(value) }
    channelB.onReceive { value -> handleB(value) }
} // runs whichever channel has a value ready first

sealed interface CounterMsg { data object Increment : CounterMsg; data class Get(val response: CompletableDeferred<Int>) : CounterMsg }

fun CoroutineScope.counterActor() = launch {
    var count = 0
    for (msg in actorChannel) when (msg) {
        is CounterMsg.Increment -> count++
        is CounterMsg.Get -> msg.response.complete(count)
    }
}

val events = MutableSharedFlow<Event>(
    replay = 1,
    extraBufferCapacity = 8,
    onBufferOverflow = BufferOverflow.DROP_OLDEST
)
// replaces BroadcastChannel(Channel.CONFLATED)

fun CoroutineScope.parseStage(input: ReceiveChannel<String>) = produce<Record> {
    for (line in input) send(parse(line))
}
fun CoroutineScope.validateStage(input: ReceiveChannel<Record>) = produce<Record> {
    for (record in input) if (record.isValid) send(record)
}
// chain: validateStage(parseStage(rawLines))

val locationChannel = Channel<Location>(Channel.CONFLATED)

launch { while (true) { locationChannel.send(getCurrentLocation()); delay(100) } }
// consumer always gets the freshest location, never queued stale ones

fun CoroutineScope.numbersFrom(start: Int) = produce<Int> {
    var x = start
    while (true) { send(x++); delay(100) }
} // channel auto-closes when this coroutine is cancelled

val channel = Channel<Int>()

launch {
    repeat(5) { channel.send(it) }
    channel.close() // signals "no more values" to receivers
}

for (value in channel) { println(value) } // loop ends automatically after close()

